What does this code optimize?
```javascript
function debounce(fn, delay) {
  let timeoutId;
  return function(...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn(...args), delay);
  };
}
const searchHandler = debounce((query) => {
  console.log('search', query);
}, 300);
```

What is the output?
```javascript
function throttle(fn, interval) {
  let lastTime = 0;
  return function(...args) {
    const now = Date.now();
    if (now - lastTime >= interval) {
      fn(...args);
      lastTime = now;
    }
  };
}
const throttledLog = throttle(() => console.log('x'), 100);
throttledLog(); // runs
throttledLog(); // skipped
throttledLog(); // skipped
```

